#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef vector<vector<ll>> Mat;

ll MOD;

Mat multiply(const Mat &A, const Mat &B) {
    int n = A.size();
    Mat C(n, vector<ll>(n, 0));
    for (int i = 0; i < n; i++) {
        for (int k = 0; k < n; k++) {
            if (A[i][k] == 0) continue;
            for (int j = 0; j < n; j++) {
                if (B[k][j] == 0) continue;
                __int128 val = (__int128)A[i][k] * B[k][j];
                C[i][j] = (ll)(( (__int128)C[i][j] + val % MOD ) % MOD);
            }
        }
    }
    return C;
}

Mat matpow(Mat A, ll power) {
    int n = A.size();
    Mat result(n, vector<ll>(n, 0));
    for (int i = 0; i < n; i++) result[i][i] = 1 % MOD;
    while (power > 0) {
        if (power & 1LL) {
            result = multiply(result, A);
        }
        A = multiply(A, A);
        power >>= 1;
    }
    return result;
}

vector<ll> multiplyVec(const Mat &A, const vector<ll> &v) {
    int n = A.size();
    vector<ll> r(n, 0);
    for (int i = 0; i < n; i++) {
        __int128 sum = 0;
        for (int j = 0; j < n; j++) {
            sum += (__int128)A[i][j] * v[j];
        }
        r[i] = (ll)(sum % MOD);
    }
    return r;
}

int main(){
    ll n, sx, sy, dx, dy, t;
    cin >> n >> sx >> sy >> dx >> dy >> t;

    MOD = n;

    ll X0 = (sx - 1) % MOD;
    ll Y0 = (sy - 1) % MOD;
    ll dx0 = ((dx % MOD) + MOD) % MOD;
    ll dy0 = ((dy % MOD) + MOD) % MOD;
    ll i0 = 0 % MOD;
    ll one = 1 % MOD;

    if (X0 < 0) X0 += MOD;
    if (Y0 < 0) Y0 += MOD;

    Mat M(6, vector<ll>(6, 0));
    M[0] = {2,1,1,0,1,2}; // X'
    M[1] = {1,2,0,1,1,2}; // Y'
    M[2] = {1,1,1,0,1,2}; // dx'
    M[3] = {1,1,0,1,1,2}; // dy'
    M[4] = {0,0,0,0,1,1}; // i'
    M[5] = {0,0,0,0,0,1}; // 1'

    // Reduce matrix entries modulo MOD just in case (not strictly necessary but safe)
    for (int i = 0; i < 6; i++)
        for (int j = 0; j < 6; j++)
            M[i][j] = ((M[i][j] % MOD) + MOD) % MOD;

    Mat Mt = matpow(M, t);

    vector<ll> v0 = {X0, Y0, dx0, dy0, i0, one};
    vector<ll> res = multiplyVec(Mt, v0);

    ll outX = res[0] + 1;
    ll outY = res[1] + 1;

    cout << outX << " " << outY << endl;

    return 0;
}
